" e="T153"><nts n="HIAT:ip" id="Seg_1213">(</nts><nts n="HIAT:ip" id="Seg_1214">(</nts><ats n="HIAT:non-pho" id="Seg_1215" s="T159" e="T153">laughing</ats><nts n="HIAT:ip" id="Seg_1216">)</nts><nts n="HIAT:ip" id="Seg_1217">)</nts><nts n="HIAT:ip" id="Seg_1218"><![CDATA[ ]]></nts></ts></ts><ts n="sc" id="Seg_1219" s="T154" e="T157"><ts n="HIAT:u" id="Seg_1221" s="T154" e="T156"><ts n="HIAT:w" id="Seg_1223" s="T154" e="T155">Eh</ts><nts n="HIAT:ip" id="Seg_1224"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_1226" s="T155" e="T155.TIE0.1">eh</ts><nts n="HIAT:ip" id="Seg_1227"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_1229" s="T155.TIE0.1" e="T156">eh</ts><nts n="HIAT:ip" id="Seg_1230">…</nts><nts n="HIAT:ip" id="Seg_1231"><![CDATA[ ]]></nts></ts><ts n="HIAT:u" id="Seg_1233" s="T156" e="T157"><nts n="HIAT:ip" id="Seg_1234">(</nts><nts n="HIAT:ip" id="Seg_1235">(</nts><ats n="HIAT:non-pho" id="Seg_1236" s="T156" e="T157">laughing</ats><nts n="HIAT:ip" id="Seg_1237">)</nts><nts n="HIAT:ip" id="Seg_1238">)</nts><nts n="HIAT:ip" id="Seg_1239"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE0"><ts n="sc" id="Seg_1240" s="T0" e="T9"><ts n="e" id="Seg_1242" s="T0" e="T1">And what comes through is your determination </ts><ts n="e" id="Seg_1244" s="T1" e="T2">at </ts><ts n="e" id="Seg_1246" s="T2" e="T3">all </ts><ts n="e" id="Seg_1248" s="T3" e="T4">cost to actually </ts><ts n="e" id="Seg_1250" s="T4" e="T5">((0,3s)) succeed. </ts><ts n="e" id="Seg_1252" s="T5" e="T6">I mean </ts><ts n="e" id="Seg_1254" s="T6" e="T7">is that a/ sort of a message that you hope comes across to </ts><ts n="e" id="Seg_1256" s="T7" e="T8">((0,4s)) to kids? </ts><ts n="e" id="Seg_1258" s="T8" e="T9">Because a lot of kids think that people just become famous over night, don't they? </ts></ts><ts n="sc" id="Seg_1259" s="T23" e="T33"><ts n="e" id="Seg_1261" s="T23" e="T24">And when/ and the other thing that comes through in the book, too, </ts><ts n="e" id="Seg_1263" s="T24" e="T25">is/ is the/ </ts><ts n="e" id="Seg_1265" s="T25" e="T26">the deep, affectionate love that yo/ that the two of you have for each other and the way that you are very ((0,4s)) </ts><ts n="e" id="Seg_1267" s="T26" e="T27">family centered. </ts><ts n="e" id="Seg_1269" s="T27" e="T28">((0,5s)) But when you first met him when you first met, the two/ yes, the two of you, </ts><ts n="e" id="Seg_1271" s="T28" e="T29">I mean was it like ((0,4s)) </ts><ts n="e" id="Seg_1273" s="T29" e="T30">bow, wham, ((0,5s)) smack? </ts><ts n="e" id="Seg_1275" s="T30" e="T31">I mean did you think: "Good God this/ this is the guy, </ts><ts n="e" id="Seg_1277" s="T31" e="T32">this is the girl I'm gonna get married to and live the rest of my life with?" </ts><ts n="e" id="Seg_1279" s="T32" e="T33">((0,4s)) David? </ts></ts><ts n="sc" id="Seg_1280" s="T34" e="T35"><ts n="e" id="Seg_1282" s="T34" e="T35">Did you?</ts></ts><ts n="sc" id="Seg_1283" s="T37" e="T40"><ts n="e" id="Seg_1285" s="T37" e="T38">((laughing)) </ts><ts n="e" id="Seg_1287" s="T38" e="T39">Was </ts><ts n="e" id="Seg_1289" s="T39" e="T40">it really like that? </ts></ts><ts n="sc" id="Seg_1290" s="T48" e="T51"><ts n="e" id="Seg_1292" s="T48" e="T49">And you obviously weren't disappointed when you got to</ts><ts n="e" id="Seg_1294" s="T49" e="T50">gether. </ts><ts n="e" id="Seg_1296" s="T50" e="T51">Ah, similar for you, Victoria? </ts></ts><ts n="sc" id="Seg_1297" s="T63" e="T71"><ts n="e" id="Seg_1299" s="T63" e="T64">W/ do/ what's been the lowest? </ts><ts n="e" id="Seg_1301" s="T64" e="T65">That's the/ the nice part of the marriage. </ts><ts n="e" id="Seg_1303" s="T65" e="T66">What's been the lowest part </ts><ts n="e" id="Seg_1305" s="T66" e="T67">of the/ of the marriage? </ts><ts n="e" id="Seg_1307" s="T67" e="T68">There is a/ there is a piece in the book, which is quite/ quite moving actually. </ts><ts n="e" id="Seg_1309" s="T68" e="T69">((0,5s)) And it's/ it's about when the/ the media accused David of having an affair. </ts><ts n="e" id="Seg_1311" s="T69" e="T70">((0,6s)) </ts><ts n="e" id="Seg_1313" s="T70" e="T71">Tell us about that. </ts></ts><ts n="sc" id="Seg_1314" s="T84" e="T87"><ts n="e" id="Seg_1316" s="T84" e="T85">Hm˙ </ts><ts n="e" id="Seg_1318" s="T85" e="T86">It wasn't true, </ts><ts n="e" id="Seg_1320" s="T86" e="T87">the story? </ts></ts><ts n="sc" id="Seg_1321" s="T88" e="T89"><ts n="e" id="Seg_1323" s="T88" e="T89">But nonetheless, it was/ it was in the papers, it was printed and/ and it affected your relationship. </ts></ts><ts n="sc" id="Seg_1324" s="T101" e="T102"><ts n="e" id="Seg_1326" s="T101" e="T102">You whacked him? </ts></ts><ts n="sc" id="Seg_1327" s="T105" e="T106"><ts n="e" id="Seg_1329" s="T105" e="T106">Three times? </ts></ts><ts n="sc" id="Seg_1330" s="T107" e="T109"><ts n="e" id="Seg_1332" s="T107" e="T108">Yeah? </ts><ts n="e" id="Seg_1334" s="T108" e="T109">Hurt you? </ts></ts><ts n="sc" id="Seg_1335" s="T110" e="T113"><ts n="e" id="Seg_1337" s="T110" e="T111">Yeah. </ts><ts n="e" id="Seg_1339" s="T111" e="T112">In fact, hurting so much that/ that's you/ you/ you were very depressed, weren't you? </ts><ts n="e" id="Seg_1341" s="T112" e="T113">You… </ts></ts><ts n="sc" id="Seg_1342" s="T114" e="T115"><ts n="e" id="Seg_1344" s="T114" e="T115">((0,6s)) Well, how depressed were you, what did you do? </ts></ts><ts n="sc" id="Seg_1345" s="T116" e="T117"><ts n="e" id="Seg_1347" s="T116" e="T117">((unv.)) </ts></ts><ts n="sc" id="Seg_1348" s="T135" e="T136"><ts n="e" id="Seg_1350" s="T135" e="T136">You were looking out the window thinking… </ts></ts><ts n="sc" id="Seg_1351" s="T137" e="T138"><ts n="e" id="Seg_1353" s="T137" e="T138">(so)</ts></ts><ts n="sc" id="Seg_1354" s="T140" e="T141"><ts n="e" id="Seg_1356" s="T140" e="T141">(to jump) </ts></ts><ts n="sc" id="Seg_1357" s="T145" e="T153"><ts n="e" id="Seg_1359" s="T145" e="T146">((laughing)) </ts><ts n="e" id="Seg_1361" s="T146" e="T147">((laughing)) </ts><ts n="e" id="Seg_1363" s="T147" e="T148">A surprising read, isn't it?</ts><ts n="e" id="Seg_1365" s="T148" e="T149">It's/ it's/ it's/ it's ve/ </ts><ts n="e" id="Seg_1367" s="T149" e="T150">it's very interesting </ts><ts n="e" id="Seg_1369" s="T150" e="T151">v/ part of the book. </ts><ts n="e" id="Seg_1371" s="T151" e="T152">I hope you got time to finish this book, you know, before </ts><ts n="e" id="Seg_1373" s="T152" e="T159">too long. </ts><ts n="e" id="Seg_1375" s="T159" e="T153">((laughing)) </ts></ts><ts n="sc" id="Seg_1376" s="T154" e="T157"><ts n="e" id="Seg_1378" s="T154" e="T155">Eh </ts><ts n="e" id="Seg_1380" s="T155" e="T156">eh eh… </ts><ts n="e" id="Seg_1382" s="T156" e="T157">((laughing)) </ts></ts></segmentation></segmented-tier><segmented-tier id="TIE1" speaker="SPK1" category="v" type="t" display-name="VIC [v]"><timeline-fork start="T9" end="T10"><tli id="T9.TIE1.1"/>
